  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Measuring the Economy$j$, $j${"readings": [{"title": "Ecclesiastes 3 (King James Version)", "url": "/portal/bible/Ecclesiastes/3"}], "body": "Economists measure how well an economy is doing with a few key numbers. Gross domestic product, or GDP, is the total market value of all final goods and services produced within a country in a given year. Real GDP is adjusted for price changes so that we can compare years fairly. Economic growth means real GDP is rising over time, which usually means more jobs and rising living standards.\n\nInflation is a general rise in prices over time, which lowers the purchasing power of money. The Consumer Price Index, or CPI, tracks the price of a typical basket of goods and services that households buy. If inflation is three percent, something that cost one hundred dollars last year costs about one hundred three dollars this year, so savings sitting in cash buy less. Deflation, a general fall in prices, can also cause trouble.\n\nThe unemployment rate is the percent of people in the labor force who are actively looking for work but do not have a job. The labor force counts people who are working or looking, so students, retirees and people who have stopped looking are not counted as unemployed.\n\nThe business cycle is the repeating pattern of expansion (growth), peak, contraction (a recession if it is serious and lasting), and trough, followed by recovery. No one can predict the exact timing. Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. Joseph's plan in Genesis 41 prepared Egypt for seven good years followed by seven lean years, a wise response to a cycle.\n\nWorked example: if wages rise four percent but prices rise six percent, workers can buy less than before. Common mistake: judging a raise by dollars alone. Compare it to inflation.\n\nYour task: (1) Define GDP, inflation, CPI and the unemployment rate. (2) Name the four phases of the business cycle. (3) Explain why a four percent raise may not be a gain when inflation is six percent.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.E.2, SS.912.E.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.E.2, SS.912.E.3", "script": "Welcome back. Listen, to manage wisely you must know how to read the signs of the economy.\n\nGross domestic product, or GDP, is the total market value of final goods and services produced in a country in a year. When real GDP rises, the economy is growing. Inflation is a general rise in prices, which lowers what your money can buy. The Consumer Price Index tracks the cost of a typical basket of goods.\n\nNow watch this. The unemployment rate is the percent of the labor force who are looking for work but do not have a job. The labor force counts people who are working or looking.\n\nThe business cycle moves through expansion, peak, contraction and trough, then recovery. A serious, lasting contraction is a recession. Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. Joseph prepared Egypt for seven lean years in Genesis 41. That is wisdom.\n\nIf your wages rise four percent and prices rise six percent, you can buy less. Compare a raise with inflation.\n\nYour task is to define GDP, inflation, CPI and unemployment, name the cycle phases and explain the raise example. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Measuring the Economy$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Government, Taxes and Trade$j$, $j${"readings": [{"title": "Matthew 22 (King James Version)", "url": "/portal/bible/Matthew/22"}], "body": "Governments provide public goods such as roads, schools, courts, police and national defense, and pay for them mostly through taxes. Common taxes include income taxes, payroll taxes that fund Social Security and Medicare, sales taxes on purchases, and property taxes on land and buildings. A progressive tax takes a larger percent from higher incomes, a proportional tax takes the same percent from everyone, and a regressive tax takes a larger share of income from lower earners.\n\nFlorida does not have a state personal income tax. The state sales tax is six percent, and many counties add a local surtax, so the rate you pay depends on where you buy. Federal income tax still applies to Florida residents. When a government spends more than it collects in a year, it runs a deficit, and the total of past deficits is the national debt. Proverbs 22:7 reminds us that the borrower is servant to the lender, a lesson for nations as well as families.\n\nJesus taught that citizens have duties. Matthew 22:21 says, Render therefore unto Caesar the things which are Caesar's; and unto God the things that are God's. Paying taxes honestly is part of good citizenship.\n\nTrade lets nations specialize. Comparative advantage means a nation or person should produce what they can make at the lowest opportunity cost and trade for the rest. Imports are goods bought from other countries, and exports are goods sold to them. A tariff is a tax on imports. Tariffs can protect some jobs, but they also raise prices for consumers, and other nations may respond with their own tariffs.\n\nWorked example: a store charges a ten dollar item plus six percent sales tax, so the total is ten dollars and sixty cents. Common mistake: forgetting local surtax and taxes when budgeting.\n\nYour task: (1) Name four kinds of taxes. (2) Explain progressive, proportional and regressive taxes. (3) Define comparative advantage and tariff.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.E.2, SS.912.E.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.E.2, SS.912.E.3", "script": "Welcome back. Listen, government and trade touch your wallet every day.\n\nGovernments provide public goods like roads, courts and defense, and pay for them mostly with taxes. Income taxes, payroll taxes, sales taxes and property taxes are the common types. A progressive tax takes a larger percent from higher incomes. A proportional tax takes the same percent. A regressive tax takes a larger share from lower earners.\n\nNow watch this. Florida has no state personal income tax. The state sales tax is six percent, and many counties add a surtax. Federal income tax still applies. When government spends more than it collects, it runs a deficit, and past deficits make up the national debt.\n\nMatthew 22:21 says, Render therefore unto Caesar the things which are Caesar's; and unto God the things that are God's. Paying taxes honestly is good citizenship.\n\nTrade lets nations specialize. Comparative advantage means producing what you make at the lowest opportunity cost and trading for the rest. A tariff is a tax on imports. It can protect some jobs but raises prices for consumers.\n\nYour task is to name four taxes, explain the three tax types and define comparative advantage and tariff. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Government, Taxes and Trade$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Income, Careers and Paychecks$j$, $j${"readings": [{"title": "2 Thessalonians 3 (King James Version)", "url": "/portal/bible/2Thessalonians/3"}], "body": "Most people earn income by working. Human capital is the knowledge, skills and health that make a worker productive. On average, people with more education and training earn more and are less likely to be unemployed, though results vary by field. Choosing a career means weighing your gifts and calling, the demand for the work, the pay, the cost of training and the lifestyle you want. Scripture honors all honest work. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. 2 Thessalonians 3:10 says, For even when we were with you, this we commanded you, that if any would not work, neither should he eat.\n\nYour gross pay is what you earn before deductions. Your net pay, or take home pay, is what you receive after deductions. Common deductions are federal income tax withholding, and FICA taxes. FICA includes Social Security at 6.2 percent and Medicare at 1.45 percent of wages, paid by the employee, and the employer pays a matching share. Florida has no state income tax to withhold. Workers may also pay for health insurance or retirement plans through payroll.\n\nWhen you start a job you complete a Form W4 so your employer withholds the right amount of federal tax, and at the end of the year you receive a Form W2 that reports your wages and the taxes withheld. A pay stub shows the details. Check it for errors.\n\nWorkers earn income in several ways: wages, salary, tips, commissions, self employment and, later, interest and dividends. Employees and independent contractors are treated differently for taxes, and contractors pay both halves of the payroll taxes.\n\nWorked example: a worker earns four hundred dollars gross. Social Security is 6.2 percent, which is 24.80 dollars, and Medicare is 1.45 percent, which is 5.80 dollars. Common mistake: budgeting from gross pay instead of net pay.\n\nYour task: (1) Define gross pay, net pay and human capital. (2) Explain FICA. (3) Calculate the FICA taxes on a six hundred dollar paycheck.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.FL", "script": "Welcome back. Listen, work is a gift, and your paycheck tells a story you must learn to read.\n\nHuman capital is the knowledge, skills and health that make you productive. On average, more education and training lead to higher pay and steadier work. Colossians 3:23 says, And whatsoever ye do, do it heartily, as to the Lord, and not unto men. Second Thessalonians 3:10 says, if any would not work, neither should he eat.\n\nNow watch this. Gross pay is what you earn before deductions. Net pay is what you take home. Deductions include federal income tax withholding and FICA. FICA is Social Security at 6.2 percent and Medicare at 1.45 percent of wages, and the employer pays a matching share. Florida has no state income tax to withhold.\n\nWhen you start a job you fill out a Form W4. At year end you receive a Form W2 showing your wages and taxes withheld. Check your pay stub for errors.\n\nAlways budget from net pay, not gross pay.\n\nYour task is to define gross pay, net pay and human capital, explain FICA and calculate FICA on a six hundred dollar paycheck. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Income, Careers and Paychecks$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Spending Wisely: Consumer Choices, Advertising and Contracts$j$, $j${"readings": [{"title": "Luke 14 (King James Version)", "url": "/portal/bible/Luke/14"}], "body": "Consumers make thousands of spending choices, and wise choices stretch every dollar. Begin with needs and wants. Needs are things required for life and work, such as food, shelter, clothing and transportation. Wants are things that are nice but not required. Comparison shopping means checking quality, price and reviews at several stores before you buy. Unit price, the price per ounce or per item, helps you compare different package sizes. Watch for total cost, including tax, shipping and fees.\n\nAdvertising is designed to persuade, not just to inform. Common techniques include celebrity endorsements, appeals to fear or popularity, limited time offers, bandwagon claims and free trials that start charging later. Ask: Who benefits if I buy this? Do I need it? Is the claim true? Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?\n\nA contract is a legally binding agreement. Before signing any contract, read it fully, understand the fees, the length, and how to cancel, and ask for a copy. Warranties promise that a product will work for a stated time. Return policies vary by store, so check them before you buy. If you are treated unfairly, you can contact the seller, your state attorney general, or the Federal Trade Commission. In Florida, you may also contact the state Department of Agriculture and Consumer Services.\n\nBe careful with subscriptions, buy now pay later plans and impulse buys. Waiting twenty four hours before a large purchase prevents many regrets.\n\nWorked example: a twelve ounce box costs three dollars, and a twenty four ounce box costs five dollars. The unit prices are twenty five cents and about twenty one cents per ounce, so the larger box is a better value if you will use it. Common mistake: buying because something is on sale when you did not need it.\n\nYour task: (1) Define unit price and comparison shopping. (2) Describe three advertising techniques. (3) List four things to check before signing a contract.\n\nFlorida standards: NLPA Economics with Financial Literacy course outcomes, SS.912.FL.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "NLPA Economics with Financial Literacy course outcomes, SS.912.FL", "script": "Welcome back. Listen, every dollar you spend is a decision, and wise decisions stretch your dollars.\n\nNeeds are things required for life and work. Wants are nice but not required. Comparison shop for quality, price and reviews. Use unit price, the price per ounce or per item, to compare package sizes. Include tax, shipping and fees in total cost.\n\nNow watch this. Advertising is designed to persuade. Watch for celebrity endorsements, fear or popularity appeals, limited time offers and free trials that start charging later. Ask yourself whether you need it and whether the claim is true. Proverbs 14:15 says, The simple believeth every word: but the prudent man looketh well to his going.\n\nLuke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it? Count the cost before you buy.\n\nA contract is a legally binding agreement. Read it fully, understand the fees, the length and how to cancel, and get a copy. Wait twenty four hours before a large purchase.\n\nYour task is to define unit price, describe three ad techniques and list four things to check before signing. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Spending Wisely: Consumer Choices, Advertising and Contracts$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: The Economy and Consumers$j$, $j${"prompt": "Write a report of at least 250 words on the economy and the consumer. Use complete sentences and label each part. Luke 14:28 says, For which of you, intending to build a tower, sitteth not down first, and counteth the cost, whether he have sufficient to finish it?\n\nPart 1: Define GDP, inflation and the unemployment rate and describe the four phases of the business cycle.\nPart 2: Explain four kinds of taxes and describe the difference between progressive, proportional and regressive taxes. Include what is true about Florida taxes.\nPart 3: Explain comparative advantage and one effect of a tariff.\nPart 4: Explain gross pay, net pay and FICA, and calculate the net pay for a sample paycheck of five hundred dollars after the two FICA taxes only.\nPart 5: Describe three ways to spend wisely and explain how to protect yourself in a contract.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 15 points. Part 4: 20 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: The Economy and Consumers$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Counting the Cost$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a purchase teens often make because of advertising, (2) names one advertising technique used, (3) explains how you would count the cost before buying, and (4) connects your answer to Luke 14:28 or Proverbs 14:15. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why is it important to compare a raise with inflation?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Counting the Cost$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Measuring the Economy$j$, $j${"questions": [{"q": "GDP is the market value of:", "options": ["All money in banks", "Government debt", "Only exports", "Final goods and services produced in a country in a year"]}, {"q": "Inflation is:", "options": ["A tax", "A rise in jobs", "A fall in prices", "A general rise in prices"]}, {"q": "The unemployment rate counts people who:", "options": ["Have stopped looking forever", "Are retired", "Are looking for work but have no job", "Are students only"]}, {"q": "The phases of the business cycle include:", "options": ["Expansion, peak, contraction and trough", "Tax and spend", "Spring and fall", "Buy and sell"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Measuring the Economy$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,2,0}'::int[], array[$j$GDP measures production.$j$,$j$It lowers purchasing power.$j$,$j$They are in the labor force and seeking work.$j$,$j$The cycle repeats.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Measuring the Economy$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Government, Taxes and Trade$j$, $j${"questions": [{"q": "A tax that takes a larger percent from higher incomes is:", "options": ["A tariff", "Progressive", "Proportional", "Regressive"]}, {"q": "Florida has no state:", "options": ["Sales tax", "Roads", "Property tax", "Personal income tax"]}, {"q": "A tariff is a tax on:", "options": ["Imports", "Wages", "Land", "Gifts"]}, {"q": "Matthew 22:21 teaches us to render to Caesar:", "options": ["Only gifts", "Nothing", "The things which are Caesar's", "Our faith"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Government, Taxes and Trade$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,0,2}'::int[], array[$j$Progressive taxes rise with income.$j$,$j$Florida has no state personal income tax.$j$,$j$It raises the price of imported goods.$j$,$j$Citizens owe honest taxes.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Government, Taxes and Trade$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Income, Careers and Paychecks$j$, $j${"questions": [{"q": "Net pay is:", "options": ["A bonus", "Pay after deductions", "Pay before taxes", "A loan"]}, {"q": "The employee share of Social Security tax is:", "options": ["50 percent", "6.2 percent", "20 percent", "0.5 percent"]}, {"q": "Human capital is:", "options": ["Money in a bank", "A kind of tax", "A machine", "Knowledge, skills and health that make workers productive"]}, {"q": "A Form W2 reports:", "options": ["Wages and taxes withheld for the year", "Your budget", "Your grades", "Your savings"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Income, Careers and Paychecks$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,3,0}'::int[], array[$j$It is your take home pay.$j$,$j$FICA includes 6.2 percent for Social Security.$j$,$j$Education and training raise productivity.$j$,$j$Employers send it after the year ends.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Income, Careers and Paychecks$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Spending Wisely: Consumer Choices, Advertising and Contracts$j$, $j${"questions": [{"q": "Unit price helps you compare:", "options": ["Price per ounce or per item", "Store names", "Colors", "Brands only"]}, {"q": "Luke 14:28 teaches us to:", "options": ["Spend quickly", "Count the cost first", "Borrow freely", "Avoid all building"]}, {"q": "Before signing a contract you should:", "options": ["Trust the salesperson only", "Read it fully and understand fees and cancellation", "Skip the details", "Sign quickly"]}, {"q": "A limited time offer is meant to:", "options": ["Teach economics", "Guarantee quality", "Lower taxes", "Create urgency to buy"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Spending Wisely: Consumer Choices, Advertising and Contracts$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3}'::int[], array[$j$It shows the better value.$j$,$j$Plan before you commit.$j$,$j$A contract is legally binding.$j$,$j$Pressure can lead to impulse buying.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Spending Wisely: Consumer Choices, Advertising and Contracts$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: The Economy and Consumers$j$, $j${"questions": [{"q": "A recession is a:", "options": ["Bank loan", "Type of tax", "Period of growth", "Serious, lasting contraction"]}, {"q": "The Consumer Price Index measures:", "options": ["Savings", "Taxes", "Wages only", "Changes in the price of a typical basket of goods"]}, {"q": "A regressive tax:", "options": ["Taxes only the rich", "Is always zero", "Is a tariff", "Takes a larger share of income from lower earners"]}, {"q": "A deficit occurs when government:", "options": ["Prints a law", "Collects more than it spends", "Cuts all taxes", "Spends more than it collects"]}, {"q": "Comparative advantage means producing what you make at the lowest:", "options": ["Tax", "Wage", "Opportunity cost", "Price"]}, {"q": "Social Security and Medicare taxes together are called:", "options": ["FDIC", "GDP", "CPI", "FICA"]}, {"q": "Net pay is smaller than gross pay because of:", "options": ["Bonuses", "Interest", "Gifts", "Deductions"]}, {"q": "Before signing a contract, you should:", "options": ["Skip cancellation terms", "Read it fully", "Ignore fees", "Rush"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Economy and Consumers$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,3,3,2,3,3,1}'::int[], array[$j$It is a downturn in the business cycle.$j$,$j$It tracks inflation.$j$,$j$The burden is heavier on lower incomes.$j$,$j$The sum of deficits is the debt.$j$,$j$Specialization and trade benefit both sides.$j$,$j$They appear on your pay stub.$j$,$j$Taxes and other deductions are subtracted.$j$,$j$A contract binds you legally.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: The Economy and Consumers$j$ on conflict (item_id) do nothing;
